{
  "missing_information": [
    {
      "category": "Trigger & Frequency",
      "gap": "What event or condition initiates a review instance and how often reviews occur",
      "why_it_matters": "Defines the entry point of the process and is essential for automating or scheduling workflow instantiation"
    },
    {
      "category": "Scope Identification",
      "gap": "How the engineer determines which parts of the document require attention",
      "why_it_matters": "Determines whether the review is full-document or delta-based, directly affecting effort estimation and automation feasibility"
    },
    {
      "category": "Review Steps & Tools",
      "gap": "The ordered activities, tools, and references the engineer uses during the review itself",
      "why_it_matters": "Required to model the core workflow steps and identify automation or decision-support opportunities"
    },
    {
      "category": "Roles & Handoffs",
      "gap": "Whether multiple roles are involved and how work passes between them",
      "why_it_matters": "Determines process complexity, parallelism, and coordination overhead for workflow reconstruction"
    },
    {
      "category": "Issue Handling & Rework",
      "gap": "What happens when issues are found, including who fixes them and whether re-review occurs",
      "why_it_matters": "Reveals loops and exception paths that are critical for accurate process modeling"
    },
    {
      "category": "Completion & Output",
      "gap": "What artifact is produced and what formal condition marks the review as complete",
      "why_it_matters": "Defines the exit point of the process and the outputs consumed by downstream steps"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers a new review instance — for example, a new document version being published, a change request being submitted, or a release milestone being reached — and roughly how frequently does this review occur?",
      "targets": ["Trigger & Frequency"],
      "source_ids": ["C1", "C12"],
      "selection_reason": "C1 and C12 address the same core need (trigger and cadence); merging them avoids redundancy while capturing both the event type and frequency in a single focused question"
    },
    {
      "id": "Q2",
      "question": "How does the engineer determine which parts of the document to review — for instance, by diffing against a previous version, working through a checklist of expected features, or reading the entire document each time?",
      "targets": ["Scope Identification"],
      "source_ids": ["C3"],
      "selection_reason": "C3 directly addresses the scoping mechanism, which is a distinct and high-value uncertainty not covered by any other candidate"
    },
    {
      "id": "Q3",
      "question": "Can you walk through the specific steps the engineer performs during the review itself — what do they check first, what tools or reference materials do they consult, and in what order do these activities typically occur?",
      "targets": ["Review Steps & Tools"],
      "source_ids": ["C5"],
      "selection_reason": "C5 targets the core review procedure in detail, which is the most critical gap for reconstructing the workflow and identifying automation opportunities"
    },
    {
      "id": "Q4",
      "question": "Is the review performed by a single engineer working alone, or are other roles involved — such as a document author, a second reviewer, or an approver — and if multiple roles participate, how does work pass between them?",
      "targets": ["Roles & Handoffs"],
      "source_ids": ["C2", "C9"],
      "selection_reason": "C2 and C9 ask essentially the same question about reviewer count and role involvement; merging them into one question eliminates redundancy while preserving the handoff dimension from C9"
    },
    {
      "id": "Q5",
      "question": "When the engineer finds an issue — whether a minor typo or a significant gap — what happens next: who is responsible for making the correction, how is the issue recorded, and does the document return to the engineer for re-review afterward?",
      "targets": ["Issue Handling & Rework"],
      "source_ids": ["C7", "C10"],
      "selection_reason": "C7 covers routine issue handling and C10 covers escalation of blocking issues; combining them into one question captures the full rework and exception path without splitting a single logical flow across two questions"
    },
    {
      "id": "Q6",
      "question": "What artifact does the engineer produce to record review findings — for example, inline annotations, a structured report, or issues in a tracking tool — and what formal condition marks the review as officially complete, such as a sign-off or a status update?",
      "targets": ["Completion & Output"],
      "source_ids": ["C6", "C11"],
      "selection_reason": "C6 addresses the output artifact and C11 addresses the completion condition; both concern the process exit point and are tightly coupled, making a merged question more coherent than two separate ones"
    }
  ]
}
